import { useTheme } from "@/app/context/ThemeContext";
import { RootStackParamList } from "@/app/types/navigationTypes";
import {
  dynamicSpacing,
  getContentMaxWidth,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { useNavigation } from "@react-navigation/native";
import { StackNavigationProp } from "@react-navigation/stack";
import { useEffect, useRef } from "react";
import {
  Animated,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";

type ExamNavProp = StackNavigationProp<RootStackParamList, "Exam">;

export default function ExamScreen() {
  const navigation = useNavigation<ExamNavProp>();
  const opacity = useRef(new Animated.Value(0)).current;
  const { theme } = useTheme() as any;
  if (!theme?.colors) return null;
  const colors = theme.colors;
  const isDarkMode = theme.dark === true;
  const backgroundColor = isDarkMode ? theme.colors.background : "#2b4353";

  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(520);

  useEffect(() => {
    Animated.timing(opacity, {
      toValue: 1,
      duration: 400,
      useNativeDriver: true,
    }).start();
  }, []);

  return (
    <View style={{ flex: 1, backgroundColor }}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            styles.contentWrapper,
            isWide && { maxWidth: contentMaxWidth },
            { paddingHorizontal: dynamicSpacing(14, 20) },
          ]}
        >
          <Animated.View style={[styles.topContent, { opacity }]}>
            <View style={styles.inner}>
              <Text style={[styles.title, { color: "#f5f5f5" }]}>
                Prüfungssimulation
              </Text>

              <View style={styles.bulletRow}>
                <Text style={[styles.bullet, { color: "#f5f5f5" }]}>❯</Text>
                <Text style={[styles.bulletText, { color: "#f5f5f5" }]}>
                  Du bearbeitest eine Prüfungssimulation mit Fragen aus den
                  Lernfeldern 7–15.
                </Text>
              </View>

              <View style={styles.bulletRow}>
                <Text style={[styles.bullet, { color: "#f5f5f5" }]}>❯</Text>
                <Text style={[styles.bulletText, { color: "#f5f5f5" }]}>
                  Am Ende erhältst du dein Ergebnis, die detaillierte Auswertung
                  findest du im Bereich Fortschritt.
                </Text>
              </View>

              <View style={styles.bulletRow}>
                <Text style={[styles.bullet, { color: "#f5f5f5" }]}>❯</Text>
                <Text style={[styles.bulletText, { color: "#f5f5f5" }]}>
                  Nach jeder Simulation kannst du eine neue starten.
                </Text>
              </View>
            </View>
          </Animated.View>
          <Text
            style={[
              styles.bulletText,
              {
                color: "#cccccc",
                textAlign: "center",
                marginTop: dynamicSpacing(40, 50),
                width: "85%",
              },
            ]}
          >
            In dieser Probeversion steht dir eine Prüfung zur Verfügung – in der
            App findest du 15 Prüfungen mit insgesamt ca. 600 Fragen.
          </Text>

          <TouchableOpacity
            style={styles.bottomButton}
            onPress={() => navigation.navigate("ExamStart")}
          >
            <Text style={styles.bottomButtonText}>Prüfung starten</Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  scrollContent: {
    alignItems: "center",
    paddingVertical: dynamicSpacing(10, 14),
  },

  contentWrapper: {
    width: "100%",
    alignItems: "center",
  },

  topContent: {
    justifyContent: "flex-start",
    alignItems: "center",
    marginTop: dynamicSpacing(60, 70),
  },

  title: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(22),
    textAlign: "center",
    marginBottom: dynamicSpacing(20, 28),
  },

  bulletRow: {
    flexDirection: "row",
    alignItems: "flex-start",
    marginTop: dynamicSpacing(20, 28),
    width: "100%",
  },

  bullet: {
    fontSize: scaleFont(20),
    marginRight: 8,
    lineHeight: scaleFont(24),
  },

  bulletText: {
    flex: 1,
    flexShrink: 1,
    flexWrap: "wrap",
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(17),
    lineHeight: scaleFont(24),
  },

  inner: {
    width: "90%",
    alignSelf: "center",
  },

  bottomButton: {
    backgroundColor: "#34b4b4",
    borderRadius: 10,
    paddingVertical: dynamicSpacing(16, 22),
    paddingHorizontal: dynamicSpacing(40, 56),
    marginTop: dynamicSpacing(50, 60),
    marginBottom: dynamicSpacing(50, 60),
  },

  bottomButtonText: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(17),
    color: "#fff",
    textAlign: "center",
  },
});
