import { useTheme } from '@/app/context/ThemeContext';
import { StyleSheet, Text, TouchableOpacity } from 'react-native';

interface NextButtonProps {
    onPress: () => void;
    active: boolean;
    text?: string;
    }

    export default function NextButton({ onPress, active, text }: NextButtonProps) {
    const { theme } = useTheme();
    return (
        <TouchableOpacity
            style={[
                styles.button,
                { backgroundColor: active ? theme.colors.primary : '#aaa' },
            ]}
            disabled={!active}
            onPress={onPress}
        >
            <Text style={styles.text}>{text || 'Weiter'}</Text>
        </TouchableOpacity>
    );
}
    const styles = StyleSheet.create({
    button: {
        alignSelf: 'center',
        borderRadius: 12,
        paddingVertical: 10,
        paddingHorizontal: 40,
    },
    text: {
        fontFamily: 'Montserrat-Bold',
        fontSize: 18,
    },
});