// app/screens/Training/QuizDropdownSlide.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { demoQuizDropdown } from "@/app/data/demoQuizDropdown";
import { hyphenateLabel } from "@/app/utils/hyphenateLabel";
import {
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import React, { useEffect, useState } from "react";
import {
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";

interface QuizDropdownSlideProps {
  quizId: number;
  selected: string | null;
  onSelect: (v: string | null) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (correctCount: number, totalCount: number) => void;
  onFeedback: (text: string) => void;
}

export default function QuizDropdownSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
  onFeedback,
}: QuizDropdownSlideProps) {
  const { theme } = useTheme();
  const { colors } = theme;
  const [quiz, setQuiz] = useState<{
    QuizId: number;
    Question: string;
    Options: string[][];
    CorrectValue: string[];
  } | null>(null);

  const [selectedValues, setSelectedValues] = useState<string[]>([]);
  const [feedback, setFeedback] = useState("");
  const [openIndexes, setOpenIndexes] = useState<{ [key: number]: boolean }>(
    {},
  );
  const [dropdownWidth, setDropdownWidth] = useState<number>(120);
  const [showCorrectAnswers, setShowCorrectAnswers] = useState<string[]>([]);
  const { width } = useOrientation();
  const isWide = width >= 768;

  useEffect(() => {
    const data = demoQuizDropdown.find((q) => q.QuizId === quizId) ?? null;
    if (!data) return;

    setQuiz(data);
    setOpenIndexes({});
    setSelectedValues(new Array(data.CorrectValue.length).fill(""));

    const longest = Math.max(
      ...data.Options.flat().map((s: string) => s.length),
    );
    const w = Math.min(280, Math.max(120, Math.round(longest * 10)));
    setDropdownWidth(w);
  }, [quizId]);

  const handleSelect = (index: number, value: string) => {
    const updated = [...selectedValues];
    updated[index] = value;
    setSelectedValues(updated);
    const allFilled = updated.every((v) => v !== "");
    onSelect(allFilled ? "ready" : null);
  };

  // --- Auswertung bei Bestätigung ---
  useEffect(() => {
    if (confirmRequested && quiz) {
      let correctCount = 0;
      quiz.CorrectValue.forEach((v: string, i: number) => {
        if (selectedValues[i] === v) correctCount++;
      });

      const total = quiz.CorrectValue.length;
      const isAllCorrect = correctCount === total;
      const isPartial = correctCount > 0 && correctCount < total;

      let message = "";
      if (isAllCorrect) message = "Gut gemacht!";
      else if (isPartial) message = "Fast richtig!";
      else message = "Leider falsch.";

      setFeedback(message);
      onFeedback(message);
      onResult(correctCount, total);
      onConfirmed();

      const wrongIndexes = (quiz.CorrectValue as string[])
        .map((v: string, i: number) => (selectedValues[i] !== v ? i : null))
        .filter((v): v is number => v !== null);

      if (wrongIndexes.length > 0) {
        // nur richtige Antworten der falsch beantworteten Felder zeigen
        const wrongCorrectValues = wrongIndexes.map(
          (i) => quiz.CorrectValue[i],
        );
        setShowCorrectAnswers(wrongCorrectValues);
      }
    }
  }, [confirmRequested]);

  if (!quiz) return null;

  return (
    <ScrollView
      contentContainerStyle={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          flexGrow: 1,
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(60, 50),
          paddingBottom: isWide
            ? dynamicSpacing(40, 60)
            : dynamicSpacing(80, 100),
        },
      ]}
      showsVerticalScrollIndicator={false}
    >
      {/* oberer Bereich */}
      <View
        style={[
          styles.topContent,
          isWide && {
            marginTop: dynamicSpacing(20, 30),
            width: "70%",
          },
        ]}
      >
        <Text style={[styles.instruction, { color: theme.colors.text }]}>
          Ergänze den Satz:
        </Text>
        <View style={styles.textContainer}>
          <View
            style={{
              flexDirection: "row",
              flexWrap: "wrap",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {quiz.Question.replace(/▢\s*,/g, "▢\u00A0,")
              .split("▢")
              .map((part: string, i: number, arr: string[]) => {
                const isLast = i === arr.length - 1;
                const hasValue = !!selectedValues[i];
                const isOpen = !!openIndexes[i];

                return (
                  <React.Fragment key={i}>
                    <Text
                      style={[styles.textContent, { color: theme.colors.text }]}
                    >
                      {part}
                    </Text>

                    {!isLast && (
                      <Text
                        onPress={() => {
                          if (!feedback) {
                            setOpenIndexes({ [i]: true }); // schließt alle anderen, öffnet nur das aktuelle
                          }
                        }}
                        style={{
                          fontSize: scaleFont(20),
                          lineHeight: scaleFont(28),
                          backgroundColor: feedback
                            ? "transparent"
                            : isOpen || hasValue
                              ? "rgba(220,220,220,0.2)"
                              : "transparent",
                          borderRadius: 6,
                          paddingHorizontal: 8,
                          paddingVertical: 2,
                          borderWidth: feedback
                            ? 0
                            : isOpen || hasValue
                              ? 2
                              : 1,
                          borderColor: feedback
                            ? "transparent"
                            : isOpen || hasValue
                              ? "#b5b5b5"
                              : "#d1d1d1",
                          fontFamily: hasValue
                            ? "Lato-Bold"
                            : "Montserrat-Regular",
                          color:
                            feedback && hasValue
                              ? selectedValues[i] === quiz.CorrectValue[i]
                                ? "#4CAF50"
                                : "#E53935"
                              : hasValue
                                ? colors.text
                                : "transparent",
                          textAlignVertical: "center",
                        }}
                      >
                        {selectedValues[i] || "    "}
                      </Text>
                    )}
                  </React.Fragment>
                );
              })}
          </View>
        </View>
      </View>

      {/* unterer Bereich */}
      {Object.entries(openIndexes).map(([i, isOpen]) =>
        isOpen ? (
          <View
            key={i}
            style={[
              styles.bottomOptionsContainer,
              {
                backgroundColor: theme.colors.background,
                position: "relative",
                bottom: undefined,
                marginTop: dynamicSpacing(40, 60),
              },
            ]}
          >
            {quiz.Options[Number(i)].map((opt: string) => (
              <TouchableOpacity
                key={opt}
                style={[
                  styles.bottomOptionButton,
                  {
                    borderColor: "#d1d1d1",
                    backgroundColor: colors.background,
                  },
                ]}
                onPress={() => {
                  handleSelect(Number(i), opt);
                  setOpenIndexes((prev) => ({ ...prev, [i]: false }));
                }}
              >
                <Text
                  style={[
                    styles.bottomOptionText,
                    { color: theme.colors.text },
                  ]}
                >
                  {hyphenateLabel(String(opt ?? ""))}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        ) : null,
      )}

      {showCorrectAnswers.length > 0 && (
        <View
          style={[
            styles.bottomOptionsContainer,
            {
              backgroundColor: theme.colors.background,
              position: "relative",
              bottom: undefined,
              marginTop: dynamicSpacing(40, 60),
              alignSelf: "center",
            },
          ]}
        >
          {showCorrectAnswers.map((opt: string) => (
            <View
              key={opt}
              style={{
                borderWidth: 1.5,
                borderColor: "#4CAF50",
                borderRadius: 8,
                backgroundColor: "#4CAF5020",
                paddingVertical: dynamicSpacing(6, 8),
                paddingHorizontal: dynamicSpacing(10, 14),
                margin: dynamicSpacing(4, 6),
              }}
            >
              <Text
                style={{
                  fontFamily: "Montserrat-Regular",
                  fontSize: scaleFont(16),
                  color: "#4CAF50",
                }}
              >
                {opt}
              </Text>
            </View>
          ))}
        </View>
      )}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(20, 30),
  },
  question: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(20),
    textAlign: "center",
    marginBottom: dynamicSpacing(30, 40),
  },
  textContainer: {
    marginBottom: dynamicSpacing(40, 50),
    alignItems: "center",
    justifyContent: "center",
  },
  textContent: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(20),
    textAlign: "center",
    lineHeight: scaleFont(28),
  },
  dropdownContainer: {
    borderWidth: 1.5,
    borderRadius: isTablet ? 14 : 12,
    marginHorizontal: dynamicSpacing(4, 6),
    marginVertical: dynamicSpacing(4, 6),
    paddingHorizontal: dynamicSpacing(8, 10),
    paddingVertical: dynamicSpacing(4, 6),
  },
  topContent: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    marginTop: dynamicSpacing(40, 50),
  },
  instruction: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(20),
    textAlign: "center",
    marginBottom: dynamicSpacing(10, 14),
    opacity: 0.8,
  },
  bottomOptionsContainer: {
    position: "absolute",
    bottom: dynamicSpacing(60, 70),
    left: 0,
    right: 0,
    flexDirection: "row",
    justifyContent: "center",
    flexWrap: "wrap",
    gap: dynamicSpacing(10, 14),
    paddingHorizontal: dynamicSpacing(20, 30),
  },
  bottomOptionButton: {
    borderWidth: 1,
    borderRadius: 8,
    minWidth: 100,
    minHeight: 44,
    justifyContent: "center",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(10, 14),
  },
  bottomOptionText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(16),
    textAlign: "center",
    includeFontPadding: false,
    textAlignVertical: "center",
  },
});
