// app/Training/SubchaptersScreen.tsx
import { useTheme } from "@/app/context/ThemeContext";
import { SafeAreaView } from "react-native-safe-area-context";
import {
  dynamicIconSize,
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "../utils/responsive";

import { Ionicons } from "@expo/vector-icons";
import { useNavigation, useRoute } from "@react-navigation/native";
import { useEffect, useState } from "react";
import {
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { DEMO_SUBCHAPTER_BY_CHAPTER } from "../data/demoAccess";
import { demoSubchapters } from "../data/demoSubchapters";

type Subchapter = {
  SubchapterId: number;
  ChapterId: number;
  SubchapterName: string;
  OrderIndex?: number;
};

export default function Subchapters() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const { chapterId, chapterTitle } = route.params || {};
  const chapterIdNum = Number(chapterId);

  const [subchapters, setSubchapters] = useState<Subchapter[]>([]);
  const { theme } = useTheme();
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(520);

  const [completedIds, setCompletedIds] = useState<number[]>([]);

  useEffect(() => {
    // Filtert alle Unterkapitel für das aktuelle Lernfeld
    const filtered = demoSubchapters.filter(
      (s) => s.ChapterId === chapterIdNum,
    );
    setSubchapters(filtered);
    setCompletedIds([]);
  }, [chapterIdNum]);

  const handlePress = (subchapter: Subchapter) => {
    navigation.navigate("SubchapterContent", {
      subchapterId: subchapter.SubchapterId,
      subchapterTitle: subchapter.SubchapterName,
      chapterId: chapterIdNum,
      chapterTitle: chapterTitle ?? "",
    });
  };

  return (
    <SafeAreaView
      style={[
        styles.mainContainer,
        { backgroundColor: theme.colors.background },
        isWide && { alignItems: "center" },
      ]}
    >
      <View style={{ flex: 1, width: "100%" }}>
        <View
          style={[
            styles.dynamicHeadingContainer,
            { backgroundColor: theme.colors.background },
          ]}
        >
          <Text style={[styles.dynamicHeading, { color: theme.colors.text }]}>
            Lernfeld {chapterIdNum + 6}
          </Text>
        </View>

        <ScrollView
          style={{ flex: 1, width: "100%" }}
          contentContainerStyle={[
            styles.scrollContent,
            { alignItems: "center" },
          ]}
          showsVerticalScrollIndicator={false}
        >
          <View
            style={[
              isWide && {
                width: "100%",
                maxWidth: contentMaxWidth,
              },
            ]}
          >
            {subchapters.map((item) => {
              const done = completedIds.includes(Number(item.SubchapterId));
              const allowedId = DEMO_SUBCHAPTER_BY_CHAPTER[chapterIdNum];
              const isDemo = item.SubchapterId === allowedId;
              const locked = !isDemo;

              return (
                <TouchableOpacity
                  key={item.SubchapterId}
                  disabled={locked}
                  style={[
                    styles.nodeContainer,
                    {
                      backgroundColor: theme.colors.card,
                      borderColor: locked ? "#A9A9A9" : "#34b4b4",
                      opacity: locked ? 0.45 : 1,
                    },
                  ]}
                  onPress={() => handlePress(item)}
                >
                  <View style={styles.iconContainer}>
                    {isDemo ? (
                      <Ionicons
                        name="play-circle"
                        size={dynamicIconSize(35, 45)}
                        color="#34b4b4"
                      />
                    ) : (
                      <Ionicons
                        name="lock-closed"
                        size={dynamicIconSize(28, 36)}
                        color="#A0A0A0"
                      />
                    )}
                  </View>

                  <Text style={[styles.nodeText, { color: theme.colors.text }]}>
                    {item.SubchapterName}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>
        </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  mainContainer: {
    flex: 1,
  },
  dynamicHeadingContainer: {
    padding: dynamicSpacing(20, 30),
    alignItems: "center",
  },
  dynamicHeading: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(22),
  },
  scrollContent: {
    padding: dynamicSpacing(16, 24),
  },
  item: {
    paddingVertical: dynamicSpacing(14, 18),
    paddingHorizontal: dynamicSpacing(20, 24),
    borderRadius: isTablet ? 16 : 12,
    marginBottom: dynamicSpacing(10, 14),
    elevation: 1,
  },
  itemText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(16),
  },
  backButton: {
    flexDirection: "row",
    alignItems: "center",
    marginLeft: dynamicSpacing(10, 14),
  },
  headerText: {
    fontSize: scaleFont(18),
    fontFamily: "Montserrat-SemiBold",
    marginLeft: dynamicSpacing(6, 10),
  },
  nodeContainer: {
    flexDirection: "row",
    alignItems: "center",
    borderRadius: isTablet ? 22 : 18,
    borderWidth: 2,
    borderColor: "#A9A9A9",
    paddingVertical: dynamicSpacing(10, 14),
    paddingHorizontal: dynamicSpacing(15, 22),
    marginVertical: dynamicSpacing(6, 10),
  },
  iconContainer: {
    width: dynamicIconSize(60, 80),
    height: dynamicIconSize(60, 80),
    justifyContent: "center",
    alignItems: "center",
    borderRadius: isTablet ? 20 : 14,
    marginRight: dynamicSpacing(15, 20),
  },
  icon: {
    width: dynamicIconSize(35, 45),
    height: dynamicIconSize(35, 45),
    tintColor: "#A9A9A9",
  },
  nodeText: {
    flex: 1,
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(17),
  },
});
