// app/Exam/QuizMissingWordSlide.tsx
import { useTheme } from "@/app/context/ThemeContext";
import { demoMissingWord } from "@/app/data/demoMissingWord";
import { hyphenateLabel } from "@/app/utils/hyphenateLabel";
import {
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { useEffect, useState } from "react";
import { InlineMath } from "react-katex";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";

interface QuizMissingWordSlideProps {
  quizId: number;
  selected: string | null;
  onSelect: (v: string | null) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (
    correctCount: number,
    totalCount: number,
    selections?: string[],
  ) => void;
  setUndoElement?: (element: React.ReactNode) => void;
}

export default function QuizMissingWordSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
  setUndoElement,
}: QuizMissingWordSlideProps) {
  const { theme, mode } = useTheme() as any;
  const isDarkMode = mode === "dark";
  const [quiz, setQuiz] = useState<any>(null);
  const [selections, setSelections] = useState<(string | null)[]>([]);
  const [activeBlank, setActiveBlank] = useState(0);
  const [formula, setFormula] = useState("");

  const { width } = useOrientation();
  const isWide = width >= 768;

  const isFormula = (value: string) => /[\\_^{}]|Δ|η|λ/.test(value);

  useEffect(() => {
    const loadQuiz = async () => {
      const data: any = demoMissingWord.find((q) => q.QuizId === quizId);

      if (!data) return;
      setQuiz(data);
      setFormula(data.Formula || "");
      const blanks = (data.TextTemplate?.match(/▢/g) || []).length;
      setSelections(Array(blanks).fill(null));
    };
    loadQuiz();
  }, [quizId]);

  useEffect(() => {
    if (confirmRequested && quiz && selections.length > 0) {
      const corrects = Array.isArray(quiz.CorrectValues)
        ? quiz.CorrectValues
        : [quiz.CorrectValue];

      const correctCount = selections.filter(
        (v, i) => v === corrects[i],
      ).length;

      // ✅ hier richtig aufrufen
      onResult(
        correctCount,
        selections.length,
        selections.filter((s): s is string => s !== null),
      );

      onConfirmed();
    }
  }, [confirmRequested]);

  useEffect(() => {
    if (!quiz?.Formula) return;

    let newFormula = quiz.Formula;
    selections.forEach((v) => {
      if (v) {
        newFormula = newFormula.replace(
          /\\square/,
          `{\\color{${confirmRequested ? "#ffffff" : "#34b4b4"}}{\\mathbf{${v}}}}`,
        );
      }
    });

    setFormula(newFormula);
  }, [confirmRequested, selections, quiz]);

  const handleSelect = (val: string) => {
    const next = [...selections];
    next[activeBlank] = val;
    setSelections(next);

    let newFormula = quiz?.Formula || "";
    next.forEach((v) => {
      if (v) {
        newFormula = newFormula.replace(
          /\\square/,
          `{\\color{${confirmRequested ? "#ffffff" : "#34b4b4"}}{\\mathbf{${v}}}}`,
        );
      }
    });
    setFormula(newFormula);

    const nextIdx = next.findIndex((v) => v === null);
    setActiveBlank(nextIdx === -1 ? activeBlank : nextIdx);

    onSelect(next.every((v) => v !== null) ? "ready" : null);
  };

  const handleUndo = () => {
    if (selections.every((v) => v === null)) return;

    const lastIndex = [...selections].reverse().findIndex((v) => v !== null);
    const idx = lastIndex === -1 ? -1 : selections.length - 1 - lastIndex;
    if (idx >= 0) {
      const next = [...selections];
      next[idx] = null;
      setSelections(next);

      let newFormula = quiz?.Formula || "";
      next.forEach((v) => {
        if (v) {
          newFormula = newFormula.replace(
            /\\square/,
            `{\\color{${confirmRequested ? "#ffffff" : "#34b4b4"}}{\\mathbf{${v}}}}`,
          );
        }
      });
      setFormula(newFormula);

      onSelect(null);
      setActiveBlank(idx);
    }
  };

  useEffect(() => {
    if (!setUndoElement) return;
    const isActive = selections.some((v) => v !== null) && !confirmRequested;
    setUndoElement(
      <TouchableOpacity
        onPress={handleUndo}
        disabled={!isActive}
        style={styles.undoButton}
      >
        <Text
          style={[
            styles.undoIcon,
            { color: isActive ? theme.colors.primary : "#a0a0a0" },
          ]}
        >
          ⌫
        </Text>
      </TouchableOpacity>,
    );
  }, [selections, confirmRequested]);

  if (!quiz || !Array.isArray(quiz.Options)) return null;

  const displayedTextParts = (quiz.TextTemplate || "").split("▢");

  return (
    <View
      style={[
        styles.container,
        {
          backgroundColor: isDarkMode ? theme.colors.background : "#34495e",
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(30, 40),
          paddingBottom: isWide
            ? dynamicSpacing(40, 60)
            : dynamicSpacing(30, 40),
          justifyContent: "flex-start",
        },
      ]}
    >
      {/* oberer Bereich */}
      <View
        style={[
          styles.topContent,
          {
            marginTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(30, 40),
            marginBottom: isWide ? dynamicSpacing(10, 20) : 0,
            width: isWide ? "90%" : "100%",
          },
        ]}
      >
        <Text
          style={[
            styles.textContent,
            {
              color: isDarkMode ? theme.colors.text : "#f5f5f5",
              marginBottom: isWide
                ? dynamicSpacing(26, 36)
                : dynamicSpacing(20, 30),
            },
          ]}
        >
          {displayedTextParts.map((part: string, i: number) => (
            <Text key={i}>
              {part}
              {i < displayedTextParts.length - 1 && (
                <Text
                  onPress={() => setActiveBlank(i)}
                  style={{
                    fontWeight: confirmRequested ? "800" : "bold",
                    color: confirmRequested
                      ? "#ececec"
                      : selections[i]
                        ? isDarkMode
                          ? theme.colors.primary
                          : "#34b4b4"
                        : isDarkMode
                          ? theme.colors.border
                          : "#a0a0a0",
                  }}
                >
                  {selections[i] ?? "_____"}
                </Text>
              )}
            </Text>
          ))}
        </Text>
        {quiz.Formula ? (
          <View
            style={{
              marginBottom: 24,
              alignItems: "center",
              width: "100%",
            }}
          >
            <div className="missing-formula">
              <InlineMath math={formula} />
            </div>
          </View>
        ) : null}
      </View>

      {/* unterer Bereich */}
      <View
        style={[
          styles.bottomOptionsContainer,
          {
            width: isWide ? "85%" : "100%",
            rowGap: isWide ? dynamicSpacing(16, 22) : dynamicSpacing(14, 18),
            columnGap: isWide ? dynamicSpacing(16, 22) : dynamicSpacing(14, 18),
            paddingBottom: isWide
              ? dynamicSpacing(40, 60)
              : dynamicSpacing(30, 40),
            marginBottom: isWide
              ? dynamicSpacing(20, 30)
              : dynamicSpacing(10, 20),
            alignSelf: "center",
          },
        ]}
      >
        {quiz.Options?.map((opt: string, i: number) => {
          const isSelected = selections[activeBlank] === opt;
          const isUsed = selections.includes(opt);

          return (
            <TouchableOpacity
              key={i}
              disabled={confirmRequested || isUsed}
              onPress={() => !confirmRequested && !isUsed && handleSelect(opt)}
              style={[
                styles.optionButton,
                (() => {
                  const isSelected = selections[activeBlank] === opt;
                  let opacity = isUsed ? 0.5 : 1;

                  if (!isDarkMode) {
                    // LIGHT MODE: altes Exam-Design (Blau/Türkis)
                    return {
                      backgroundColor: isUsed
                        ? "#34495e60"
                        : isSelected && !confirmRequested
                          ? "#8fc2c230"
                          : "#34495e",
                      borderColor: "#8fc2c2",
                      borderWidth: isSelected ? 3 : 1,
                      opacity,
                    };
                  }

                  // DARK MODE: wie die anderen Quizzes (Card + heller Rand)
                  let bgColor = theme.colors.card;
                  let borderColor = theme.colors.border;
                  let borderWidth = 1.5;

                  if (isSelected && !confirmRequested) {
                    bgColor = theme.colors.card;
                    borderColor = "#d1d1d1";
                    borderWidth = 2;
                  }

                  return {
                    backgroundColor: bgColor,
                    borderColor,
                    borderWidth,
                    opacity,
                  };
                })(),
              ]}
            >
              {isUsed ? (
                <Text style={{ opacity: 0 }}>.</Text>
              ) : isFormula(String(opt ?? "")) ? (
                <View style={{ alignItems: "center", width: "100%" }}>
                  <InlineMath math={String(opt)} />
                </View>
              ) : (
                <Text
                  style={[
                    styles.optionText,
                    { color: isDarkMode ? theme.colors.text : "#f5f5f5" },
                  ]}
                >
                  {hyphenateLabel(String(opt ?? ""))}
                </Text>
              )}
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "center",
    padding: dynamicSpacing(20, 28),
  },
  topContent: {
    flex: 1,
    justifyContent: "flex-start",
    alignItems: "center",
    marginTop: dynamicSpacing(30, 40),
  },
  bottomOptionsContainer: {
    flexDirection: "row",
    flexWrap: "wrap",
    justifyContent: "center",
    columnGap: dynamicSpacing(14, 18),
    rowGap: dynamicSpacing(14, 18),
    paddingBottom: dynamicSpacing(30, 40),
    marginBottom: dynamicSpacing(10, 20),
  },
  question: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(18),
    lineHeight: scaleFont(26),
    textAlign: "center",
    color: "#f5f5f5",
    marginBottom: dynamicSpacing(20, 30),
  },
  textContainer: {
    marginBottom: dynamicSpacing(50, 60),
    alignItems: "center",
  },
  textContent: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(20),
    textAlign: "center",
    lineHeight: scaleFont(28),
  },
  optionsContainer: {
    width: "90%",
    flexDirection: "column",
    flexWrap: "wrap",
    justifyContent: "center",
    columnGap: dynamicSpacing(14, 18),
    rowGap: dynamicSpacing(14, 18),
  },
  optionButton: {
    width: "90%",
    paddingVertical: dynamicSpacing(14, 20),
    borderRadius: isTablet ? 14 : 12,
    borderWidth: 1.5,
    alignItems: "center",
  },
  optionText: {
    fontFamily: "Montserrat-SemiBold",
    fontSize: scaleFont(17),
    textAlign: "center",
  },
  undoButton: {
    padding: dynamicSpacing(6, 10),
    backgroundColor: "transparent",
    borderWidth: 0,
    justifyContent: "center",
    alignItems: "center",
  },
  undoIcon: {
    fontSize: scaleFont(26),
    color: "#666",
  },
});
