// ExamOverviewScreen.tsx

import { useTheme } from "@/app/context/ThemeContext";
import {
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { Colors } from "@/constants/theme";
import { useEffect, useState } from "react";
import { SafeAreaView } from "react-native-safe-area-context";
import { fetchAllExamResultsWeb } from "../utils/userResultsWeb";

import {
  FlatList,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";

export default function ExamOverviewScreen() {
  const { mode } = useTheme();
  const themeColors = Colors[mode];

  const [openExamId, setOpenExamId] = useState<number | null>(null);
  const [exams, setExams] = useState<any[]>([]);
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(700);

  useEffect(() => {
    (async () => {
      const results = await fetchAllExamResultsWeb();
      const parsed = results.map((r: any) => ({
        id: r.ExamResultId,
        date: new Date(r.Timestamp).toLocaleDateString("de-DE"),
        scoreText: `${r.Score}/${r.MaxScore}`,
        scorePercent: Math.round((r.Score / r.MaxScore) * 100),
        answers: JSON.parse(r.AnswersJSON || "[]"),
      }));

      // Nur die letzten 5 Prüfungen anzeigen (neueste zuerst)
      const latestFive = parsed
        .sort((a: any, b: any) => b.id - a.id)
        .slice(0, 5);
      setExams(latestFive);
    })();
  }, []);

  const renderExam = ({ item }: { item: any }) => {
    const isOpen = openExamId === item.id;

    return (
      <View
        style={[
          styles.card,
          {
            backgroundColor: themeColors.card,
            width: isWide ? "80%" : "100%",
            alignSelf: "center",
          },
        ]}
      >
        <TouchableOpacity
          style={styles.headerRow}
          onPress={() => setOpenExamId(isOpen ? null : item.id)}
        >
          <View>
            <Text style={[styles.cardTitle, { color: themeColors.text }]}>
              Prüfung vom {item.date}
            </Text>
            <Text style={[styles.meta, { color: themeColors.text }]}>
              Ergebnis: {item.scorePercent}% ({item.scoreText})
            </Text>
          </View>
          <Text style={[styles.arrow, { color: themeColors.text }]}>
            {isOpen ? "▲" : "▼"}
          </Text>
        </TouchableOpacity>

        {isOpen && (
          <View style={styles.dropdown}>
            {item.answers.map((a: any, i: number) => {
              const totalQuestions = item.answers.length;
              const userText =
                a.options?.find((o: any) => o.OptionKey === a.userAnswer)
                  ?.OptionText || a.userAnswer;
              const correctText =
                a.options?.find((o: any) => o.OptionKey === a.correctAnswer)
                  ?.OptionText || a.correctAnswer;

              // 🟩 Spezialbehandlung für Lückentext-Fragen
              if (a.type === "missing") {
                const userArr = Array.isArray(a.userAnswer)
                  ? a.userAnswer
                  : JSON.parse(a.userAnswer || "[]");
                const correctArr = Array.isArray(a.correctAnswer)
                  ? a.correctAnswer
                  : JSON.parse(a.correctAnswer || "[]");
                const parts = (a.questionText || "").split("▢");

                const allCorrect = userArr.every(
                  (v: string, i: number) => v === correctArr[i],
                );

                const renderSentence = (
                  values: string[],
                  colorMap?: string[],
                ) =>
                  parts.map((p: string, i: number) => (
                    <Text
                      key={i}
                      style={[styles.questionText, { color: themeColors.text }]}
                    >
                      {p}
                      {i < values.length && (
                        <Text
                          style={{
                            fontFamily: "OpenSans-SemiBold",
                            color: colorMap ? colorMap[i] : "#4CAF50",
                          }}
                        >
                          {values[i]}
                        </Text>
                      )}
                    </Text>
                  ));

                return (
                  <View key={i} style={styles.questionBox}>
                    <View style={styles.rowBetween}>
                      {/* Counter */}
                      <Text
                        style={[
                          styles.counterSmall,
                          { color: themeColors.text },
                        ]}
                      >
                        {i + 1}/{totalQuestions}
                      </Text>
                      <Text
                        style={{
                          fontSize: scaleFont(10),
                          color: a.isCorrect ? "#4CAF50" : "#E53935",
                        }}
                      >
                        {a.isCorrect ? "✔️" : "❌"}
                      </Text>
                    </View>

                    {/* Nutzertext */}
                    <Text style={{ marginTop: 4 }}>
                      {allCorrect
                        ? renderSentence(userArr)
                        : renderSentence(
                            userArr,
                            userArr.map((v: string, idx: number) =>
                              v === correctArr[idx] ? "#4CAF50" : "#E53935",
                            ),
                          )}
                    </Text>

                    {/* Richtiger Satz darunter, falls Fehler */}
                    {!allCorrect && (
                      <Text style={{ marginTop: 12 }}>
                        {renderSentence(
                          correctArr,
                          correctArr.map(() => "#4CAF50"),
                        )}
                      </Text>
                    )}
                  </View>
                );
              }

              // 🟦 Standardanzeige (Multiple Choice usw.)
              return (
                <View key={i} style={styles.questionBox}>
                  <View style={styles.rowBetween}>
                    <Text
                      style={[styles.counterSmall, { color: themeColors.text }]}
                    >
                      {i + 1}/{totalQuestions}
                    </Text>
                    <Text
                      style={
                        a.isCorrect ? styles.correctMark : styles.wrongMark
                      }
                    >
                      {a.isCorrect ? "✔️" : "❌"}
                    </Text>
                  </View>

                  <Text
                    style={[
                      styles.questionText,
                      { color: themeColors.text, marginTop: 4 },
                    ]}
                  >
                    {a.questionText}
                  </Text>
                  <Text
                    style={[
                      a.isCorrect ? styles.correctAnswer : styles.wrongAnswer,
                      { fontFamily: "OpenSans-SemiBold" },
                    ]}
                  >
                    {userText}
                  </Text>
                  {!a.isCorrect && (
                    <View style={{ marginTop: 10 }}>
                      <Text
                        style={[
                          styles.correctAnswer,
                          { fontFamily: "OpenSans-SemiBold" },
                        ]}
                      >
                        {correctText}
                      </Text>
                    </View>
                  )}
                </View>
              );
            })}
          </View>
        )}
      </View>
    );
  };

  return (
    <SafeAreaView
      style={{
        flex: 1,
        backgroundColor: isWide ? "#f8f8f8" : themeColors.background,
        alignItems: isWide ? "center" : undefined,
      }}
    >
      <View
        style={[
          { flex: 1, width: "100%" },
          isWide && {
            maxWidth: contentMaxWidth,
            borderRadius: 16,
            backgroundColor: themeColors.background,
          },
        ]}
      >
        <FlatList
          data={exams}
          renderItem={renderExam}
          keyExtractor={(item) => item.id.toString()}
          showsVerticalScrollIndicator={false}
          contentContainerStyle={{
            paddingHorizontal: dynamicSpacing(20, 40),
            paddingVertical: dynamicSpacing(24, 30),
          }}
        />
      </View>
    </SafeAreaView>
  );
}

const ORANGE = "#34b4b4";

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  sectionLabel: {
    fontFamily: "Montserrat-SemiBold",
    fontSize: scaleFont(18),
    letterSpacing: 0.2,
    opacity: 0.7,
    marginBottom: dynamicSpacing(12, 16),
  },
  card: {
    borderRadius: isTablet ? 20 : 16,
    padding: dynamicSpacing(16, 22),
    marginBottom: dynamicSpacing(20, 28),
    shadowColor: "#000",
    shadowOpacity: 0.06,
    shadowRadius: 8,
    shadowOffset: { width: 0, height: 4 },
    elevation: 2,
    borderWidth: 0.6,
    borderColor: ORANGE,
  },
  headerRow: {
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "center",
  },
  cardTitle: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(18),
    letterSpacing: 0.2,
  },
  meta: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(13),
    opacity: 0.8,
    marginTop: 2,
  },
  arrow: {
    fontSize: scaleFont(16),
    opacity: 0.8,
  },
  dropdown: {
    marginTop: dynamicSpacing(12, 16),
  },
  questionBox: {
    borderBottomWidth: 1,
    borderBottomColor: "rgba(0,0,0,0.1)",
    paddingVertical: dynamicSpacing(10, 14),
  },
  rowBetween: {
    flexDirection: "row",
    justifyContent: "space-between",
  },
  counterSmall: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(12),
    opacity: 0.8,
  },
  questionText: {
    fontFamily: "OpenSans-Regular",
    fontSize: scaleFont(16),
    flex: 1,
    flexWrap: "wrap",
    paddingRight: 6,
  },
  correctMark: {
    color: "#4CAF50",
    fontSize: scaleFont(10),
  },
  wrongMark: {
    color: "#E53935",
    fontSize: scaleFont(10),
  },
  correctAnswer: {
    color: "#4CAF50",
    marginTop: 4,
    fontFamily: "OpenSans-Regular",
    fontSize: scaleFont(16),
  },
  wrongAnswer: {
    color: "#E53935",
    marginTop: 4,
    fontFamily: "OpenSans-Regular",
    fontSize: scaleFont(16),
  },
  correctFallback: {
    opacity: 0.8,
    marginTop: 2,
    fontFamily: "OpenSans-Regular",
    fontSize: scaleFont(13),
  },
});
