import "katex/dist/katex.min.css";
import React, { useEffect } from "react";
import MainNavigatorWeb from "./app/navigation/MainNavigatorWeb";
import "./index.css";
import "./katex-fix.css";

export default function App() {
  useEffect(() => {
    const originalError = console.error;
    console.error = (...args) => {
      originalError(...args);
      alert("ERROR: " + JSON.stringify(args));
    };
  }, []);

  return <MainNavigatorWeb />;
}
