// app/Exam/QuizMultipleChoiceSlide.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { demoMultipleChoice } from "@/app/data/demoMultipleChoice";
import { hyphenateLabel } from "@/app/utils/hyphenateLabel";
import {
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { useEffect, useState } from "react";
import { InlineMath } from "react-katex";
import {
  Platform,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";

interface QuizMultipleChoiceSlideProps {
  quizId: number;
  selected: string | null;
  onSelect: (v: string) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (correctCount: number, totalCount: number) => void;
}

export default function QuizMultipleChoiceSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
}: QuizMultipleChoiceSlideProps) {
  const { theme, mode } = useTheme() as any;
  const isDarkMode = mode === "dark";
  const [quiz, setQuiz] = useState<any>(null);
  const { width } = useOrientation();
  const isWide = width >= 768; // Tablet/Chromebook Landscape

  useEffect(() => {
    const loadQuiz = async () => {
      const data: any = demoMultipleChoice.find((q) => q.QuizId === quizId);

      if (!data) return;
      setQuiz(data);
    };
    loadQuiz();
  }, [quizId]);

  useEffect(() => {
    if (confirmRequested && selected && quiz) {
      const isCorrect = selected === quiz.CorrectOption;
      // → 1 Punkt wenn richtig, 0 wenn falsch
      onResult(isCorrect ? 1 : 0, 1);

      onConfirmed();
    }
  }, [confirmRequested]);

  if (!quiz) return null;

  const optionKeys = ["A", "B", "C", ...(quiz.OptionD ? ["D"] : [])];

  return (
    <View
      style={[
        styles.container,
        {
          backgroundColor: isDarkMode ? theme.colors.background : "#34495e",
          paddingTop: isWide ? dynamicSpacing(20, 30) : dynamicSpacing(30, 40),
          paddingBottom: isWide
            ? dynamicSpacing(40, 60)
            : dynamicSpacing(30, 40),
          justifyContent: "flex-start",
        },
      ]}
    >
      <View style={styles.topContent}>
        <Text
          style={[
            styles.question,
            { color: isDarkMode ? theme.colors.text : "#f5f5f5" },
          ]}
        >
          {quiz.QuestionText}
        </Text>
      </View>

      <View style={styles.optionsContainer}>
        {optionKeys.map((key) => {
          const option = String(quiz[`Option${key}`] ?? "");
          const isFormula = option.includes("\\") || option.includes("_");
          const isSelected = selected === key;
          return (
            <TouchableOpacity
              key={key}
              disabled={confirmRequested}
              onPress={() => !confirmRequested && onSelect(key)}
              style={[
                styles.optionButton,
                (() => {
                  const isSelected = selected === key;

                  if (!isDarkMode) {
                    // LIGHT MODE: leicht hervorgehoben bei Auswahl, fetter Rand nach Bestätigung
                    let borderColor = "#8fc2c2";
                    let borderWidth = isSelected
                      ? confirmRequested
                        ? 3
                        : 2
                      : 0.5;
                    let backgroundColor = isSelected ? "#3d5b75" : "#34495e";

                    return { backgroundColor, borderColor, borderWidth };
                  }

                  // DARK MODE
                  let bgColor = theme.colors.card;
                  let borderColor = theme.colors.border;
                  let borderWidth = 1.5;

                  if (isSelected) {
                    bgColor = theme.colors.card;
                    borderColor = confirmRequested ? "#d1d1d1" : "#34b4b4";
                    borderWidth = confirmRequested ? 3 : 2;
                  }

                  return { backgroundColor: bgColor, borderColor, borderWidth };
                })(),
              ]}
            >
              {isFormula && Platform.OS === "web" ? (
                <View style={{ alignItems: "center", width: "100%" }}>
                  <InlineMath math={option} />
                </View>
              ) : (
                <Text
                  style={[
                    styles.optionText,
                    { color: isDarkMode ? theme.colors.text : "#f5f5f5" },
                  ]}
                >
                  {isFormula ? option : hyphenateLabel(option)}
                </Text>
              )}
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "center",
    padding: dynamicSpacing(20, 28),
  },
  topContent: {
    flex: 1,
    justifyContent: "flex-start",
    alignItems: "center",
    marginTop: dynamicSpacing(20, 30),
  },
  question: {
    fontFamily: "Lato-Regular",
    fontSize: scaleFont(20),
    lineHeight: scaleFont(28),
    textAlign: "center",
    marginBottom: dynamicSpacing(10, 20),
  },
  optionsContainer: {
    width: "100%",
    gap: dynamicSpacing(20, 28),
    paddingBottom: dynamicSpacing(30, 40),
    marginBottom: dynamicSpacing(20, 30), // exakt wie MissingWord
  },
  optionButton: {
    borderRadius: isTablet ? 14 : 10,
    paddingVertical: dynamicSpacing(12, 16),
    paddingHorizontal: dynamicSpacing(10, 16),
  },
  optionText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(17),
    textAlign: "center",
  },
});
