// userResultsWeb.ts

import AsyncStorage from "@react-native-async-storage/async-storage";

export async function saveUserResultWeb(
  subchapterId: number,
  mode: "training" | "exam",
  points: number,
  maxPoints: number,
) {
  try {
    const newEntry = {
      id: subchapterId,
      mode,
      points,
      maxPoints,
      date: new Date().toISOString(),
    };

    const existing = await AsyncStorage.getItem("userResults");
    const all = existing ? JSON.parse(existing) : [];

    // Vorhandene ersetzen
    const filtered = all.filter((r: any) => r.id !== subchapterId);
    filtered.push(newEntry);

    await AsyncStorage.setItem("userResults", JSON.stringify(filtered));
  } catch (err) {
    console.error("Fehler beim Speichern:", err);
  }
}

export async function getUserResultsWeb() {
  const data = await AsyncStorage.getItem("userResults");
  return data ? JSON.parse(data) : [];
}

export async function markLearningDayWeb() {
  const today = new Date().toISOString().split("T")[0]; // yyyy-mm-dd
  const existing = await AsyncStorage.getItem("learningDays");
  const all = existing ? JSON.parse(existing) : [];

  if (!all.includes(today)) {
    all.push(today);
    await AsyncStorage.setItem("learningDays", JSON.stringify(all));
  }
}

/**
 * Speichert ein abgeschlossenes Prüfungs-Ergebnis (analog zur App).
 */
export async function saveExamResultWeb(
  score: number,
  maxScore: number,
  answers: any[],
) {
  try {
    const timestamp = new Date().toISOString();
    const newResult = {
      id: Date.now(),
      timestamp,
      score,
      maxScore,
      answers,
    };

    const existing = await AsyncStorage.getItem("examResults");
    const parsed = existing ? JSON.parse(existing) : [];

    parsed.push(newResult);
    await AsyncStorage.setItem("examResults", JSON.stringify(parsed));
  } catch (e) {
    console.error("Error saving exam result:", e);
  }
}

/**
 * Ruft alle gespeicherten Prüfungs-Ergebnisse aus dem Web-Speicher ab.
 */
export async function fetchAllExamResultsWeb() {
  try {
    const existing = await AsyncStorage.getItem("examResults");
    return existing ? JSON.parse(existing) : [];
  } catch (e) {
    console.error("Error loading exam results:", e);
    return [];
  }
}

/**
 * Ruft alle Trainings-Ergebnisse ab (analog zu fetchAllUserResults).
 */
export async function fetchAllUserResultsWeb() {
  try {
    const data = await AsyncStorage.getItem("userResults");
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Error loading user results:", e);
    return [];
  }
}

/**
 * Ermittelt Stärken & Schwächen basierend auf gespeicherten Trainingsdaten.
 */
export async function getStrengthWeaknessWeb() {
  const allResults = await fetchAllUserResultsWeb();
  if (!allResults.length) return { top: [], worst: null };

  // Gruppieren nach Thema/Subchapter
  const topicStats: Record<
    string,
    { name: string; points: number; max: number }
  > = {};

  for (const r of allResults) {
    const key = String(r.id ?? r.SubchapterId ?? "unknown");
    if (!topicStats[key])
      topicStats[key] = {
        name: r.name ?? `Thema ${key}`,
        points: 0,
        max: 0,
      };
    topicStats[key].points += r.points ?? 0;
    topicStats[key].max += r.maxPoints ?? 0;
  }

  const ratios = Object.values(topicStats).map((t) => ({
    name: t.name,
    ratio: t.max > 0 ? t.points / t.max : 0,
  }));

  const sorted = ratios.sort((a, b) => b.ratio - a.ratio);
  return {
    top: sorted.slice(0, 3),
    worst: sorted.length ? sorted[sorted.length - 1] : null,
  };
}
