import { createStackNavigator } from "@react-navigation/stack";
import ChaptersScreen from "../Training/ChaptersScreen";
import OutroScreen from "../Training/OutroScreen";
import SubchapterContentScreen from "../Training/SubchapterContent";
import Subchapters from "../Training/SubchaptersScreen";

const Stack = createStackNavigator();

export default function TrainingNavigatorWeb() {
  return (
    <Stack.Navigator
      screenOptions={{
        cardStyle: { flex: 1, overflow: "visible" },
      }}
    >
      <Stack.Screen
        name="Chapters"
        component={ChaptersScreen}
        options={{ headerShown: true, title: "Start" }}
      />
      <Stack.Screen
        name="Subchapters"
        component={Subchapters}
        options={{ headerShown: true, title: "Lernfelder" }}
      />
      <Stack.Screen
        name="SubchapterContent"
        component={SubchapterContentScreen}
        options={{ headerShown: false }}
      />
      <Stack.Screen
        name="OutroScreen"
        component={OutroScreen}
        options={{ headerShown: false }}
      />
    </Stack.Navigator>
  );
}
