// app/navigation/MainNavigatorWeb.tsx

import { NavigationContainer } from "@react-navigation/native";
import { createStackNavigator } from "@react-navigation/stack";
import HomeScreen from "../Home/HomeScreen";
import ExamOverviewScreen from "../Progress/ExamOverviewScreen";
import ImpressumScreen from "../Settings/ImpressumScreen";
import PrivacyPolicyScreen from "../Settings/PrivacyPolicyScreen";
import UpdatesInfoScreen from "../Settings/UpdatesInfoScreen";
import BottomTabsWeb from "./BottomTabsWeb";
import ExamNavigator from "./ExamNavigatorWeb";
import TrainingNavigatorWeb from "./TrainingNavigatorWeb";

const Stack = createStackNavigator();

export default function MainNavigatorWeb() {
  return (
    <NavigationContainer>
      <Stack.Navigator>
        <Stack.Screen
          name="HomeTabs"
          component={BottomTabsWeb}
          options={{ headerShown: false }}
        />
        <Stack.Screen
          name="Home"
          component={HomeScreen}
          options={{ headerShown: true }}
        />
        <Stack.Screen
          name="Streak"
          component={require("../Home/StreakScreen").default}
          options={{ title: "Start" }}
        />
        <Stack.Screen
          name="Training"
          component={TrainingNavigatorWeb}
          options={{ headerShown: false }}
        />
        <Stack.Screen
          name="ImpressumScreen"
          component={ImpressumScreen}
          options={{ headerShown: true }}
        />
        <Stack.Screen
          name="PrivacyPolicyScreen"
          component={PrivacyPolicyScreen}
          options={{ headerShown: true }}
        />
        <Stack.Screen
          name="UpdatesInfoScreen"
          component={UpdatesInfoScreen}
          options={{ headerShown: true }}
        />
        <Stack.Screen
          name="Exam"
          component={ExamNavigator}
          options={{ headerShown: false }}
        />
        <Stack.Screen
          name="ExamOverview"
          component={ExamOverviewScreen}
          options={{ title: "Fortschritt" }}
        />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
